#!/usr/bin/env bash
# seq2cause-bench — l / latent / seeds 0–4 — the per-sequence truth rule forced-ok-counterfactual, generated 2026-11-11
# (plans/per-sequence-rules.md, addendum 2026-11-11). Per corpus: pull the engine tier (the score tier, the
# oracle tables and the engine's three inputs); per grain build the truth file of the read that holds
# trace/core/shipped/frozen (truthbuild re-runs the touched shards and refuses unless they equal the
# oracle tables), then score that cell and the three floor rows twice: under first-caller-parent into
# out/<corpus>/identity/ (must equal the landed records) and under forced-ok-counterfactual into
# out/<corpus>/results/. The reads are the landed test reads, fetched as input artifacts; no method runs
# and there is no GPU work. Sizing: the re-runs stay under 2 GB; the host is bought for the target that
# every command loads (l: about 20 GiB at the session grain on a 64 GiB host).
# One command per line; the runner's cwd is the harness directory; set -e stops at the first failure.
set -euo pipefail

python -m seq2causebench.pull --repo chadyuk/trace-bench --revision v0.3.0 --rung l --variant latent --seed 0 --tier engine --dest corpora --output-folder out/l-latent-s0/pull-engine

python -m seq2causebench.truthbuild --corpus corpora/instances/l/latent/seed=0 --run-dir input/l-latent-s0/test-read/discover-request-core-all-c1-N32 --max-lag 63 --shards auto --null-forcing-ops 10 --output-folder out/l-latent-s0/results/truth-forced-ok-counterfactual/request
python -m seq2causebench.seqscore --corpus corpora/instances/l/latent/seed=0 --run-dir input/l-latent-s0/test-read/discover-request-core-all-c1-N32 --cell trace/core/shipped/frozen/request --max-lag 63 --rule first-caller-parent --truth-file none --output-folder out/l-latent-s0/identity/trace/core/shipped/frozen/request/seqscore
python -m seq2causebench.floorseq --corpus corpora/instances/l/latent/seed=0 --read-dir input/l-latent-s0/test-read/discover-request-core-all-c1-N32 --reference-cell trace/core/shipped/frozen/request --reference-seqscore out/l-latent-s0/identity/trace/core/shipped/frozen/request/seqscore/seqscore.json --floor-read results/l/latent/seed=0/test-read/floors-request --floor-cell floor/topology/none/frozen/request --row broadcast --max-lag 63 --rule first-caller-parent --truth-file none --output-folder out/l-latent-s0/identity/floor/topology/none/frozen/request/seqscore-broadcast-on-trace-core
python -m seq2causebench.floorseq --corpus corpora/instances/l/latent/seed=0 --read-dir input/l-latent-s0/test-read/discover-request-core-all-c1-N32 --reference-cell trace/core/shipped/frozen/request --reference-seqscore out/l-latent-s0/identity/trace/core/shipped/frozen/request/seqscore/seqscore.json --floor-read results/l/latent/seed=0/test-read/floors-request --floor-cell floor/bigram/none/frozen/request --row broadcast --max-lag 63 --rule first-caller-parent --truth-file none --output-folder out/l-latent-s0/identity/floor/bigram/none/frozen/request/seqscore-broadcast-on-trace-core
