python -m seq2causebench.seqscore --corpus corpora/instances/l/latent/seed=0 --run-dir input/l-latent-s0/test-read/discover-request-core-all-c1-N32 --cell trace/core/shipped/frozen/request --max-lag 63 --rule forced-ok-counterfactual --truth-file out/l-latent-s0/results/truth-forced-ok-counterfactual/request/seqtruth-forced-ok-counterfactual-request.json --output-folder out/l-latent-s0/results/trace/core/shipped/frozen/request/seqscore-forced-ok-counterfactual
